"use client";import {useState} from 'react';export default function Ai(){const[topic,setTopic]=useState('Linux permissions'),[difficulty,setDifficulty]=useState('easy'),[output,setOutput]=useState(''),[busy,setBusy]=useState(false);async function generate(){setBusy(true);const r=await fetch('/api/ai/generate',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({topic,difficulty})});const d=await r.json();setOutput(d.error||JSON.stringify(d.draft,null,2));setBusy(false)}return <div className="panel max-w-3xl"><h1>AI Generator Soal</h1><label>Topik</label><input value={topic} onChange={e=>setTopic(e.target.value)}/><label>Kesulitan</label><select value={difficulty} onChange={e=>setDifficulty(e.target.value)}>{['easy','medium','hard'].map(x=><option key={x}>{x}</option>)}</select><button className="mt-4" onClick={generate} disabled={busy}>{busy?'Memproses...':'Generate draft'}</button><pre className="mt-5 whitespace-pre-wrap text-sm">{output}</pre><p className="muted">Output AI adalah draft; jangan publikasikan tanpa review dan pembuatan validator.</p></div>}